fn longest_increasing_streak(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }

    let mut max_streak = 1;
    let mut curr_streak = 1;

    for i in 1..nums.len() {
        if nums[i] > nums[i - 1] {
            curr_streak += 1;
            if curr_streak > max_streak {
                max_streak = curr_streak;
            }
        } else {
            curr_streak = 1;
        }
    }

    max_streak
}